# Map CSV names to phone numbers and fetch latest message for each
csv_names = ["Cory", "Edwin", "Glenn", "Anita", "Debra", "Morgan", "Kevin", "Kristin", "Melissa", "Norman", "Robin"]
name_to_phone = {}
for c in all_contacts:
    name_to_phone[c['first_name']] = c['phone_number']

# Fetch latest message for each friend
latest_messages = {}
for name in csv_names:
    phone = name_to_phone.get(name)
    if phone:
        msgs = apis.phone.search_text_messages(access_token=phone_login['access_token'], phone_number=phone, only_latest_per_contact=True, page_limit=1)
        if msgs:
            latest_messages[name] = msgs[0]
            print(f"{name}: {msgs[0]['message']} (sent {msgs[0]['sent_at']})")
        else:
            print(f"{name}: no messages found")
    else:
        print(f"{name}: no phone number found")

